Item.setState.source:
func setState(newState, withNextEvent: bool = false, event = null):
	Game.combatLog.snapshotItemState(self, newState, withNextEvent, event)
	onStateChanged(newState)

CombatLog.snapshotItemState.source:
func snapshotItemState(item, state, withNextEvent: bool, event: CombatEvent):
	NativeRandomObserver.entry("Core/CombatLog.gd::snapshotItemState", self, {"item": item, "state": state, "withNextEvent": withNextEvent, "event": event})
	var playerId = item.character().playerId
	var connectedEventNum = eventNum
	if event != null:
		connectedEventNum = event.id
	elif withNextEvent:
		connectedEventNum += 1

	statLoggers[playerId].logItemState(item, state, connectedEventNum)


	if loggingFinished:
		activeItemState[item] = state
	NativeRandomObserver.leave("Core/CombatLog.gd::snapshotItemState", self, null, "return_implicit")

CombatLog.onPrepare.source:
func onPrepare():
	var items = Game.PLAYER.INVENTORY.getItemsAndGems() + Game.OPPONENT.INVENTORY.getItemsAndGems()
	for character in [Game.PLAYER, Game.OPPONENT]:
		for stat in Character.Stat:
			snapshotCharacterStat(character, Character.Stat[stat])

		for stackType in Game.getStacks():
			snapshotStack(character, stackType)

		var statLogger: CombatStatLogger = statLoggers[character.playerId]
		for item in items:

			statLogger.prepareItem(item)

		for metric in Game.ItemMetrics.values():
			for type in statLogger.metricHistories[metric]:
				statLogger.logMetric(metric, type, 0, eventNum)

		globalStatHistories[GlobalStat.TimeAdvance].addValue(0.0, eventNum)

StatHistory.addValue.source:
func addValue(eventNum, value):
	if values.empty() or not Util.equals(values[ - 1], value):
		eventNumbers.push_back(eventNum)
		values.push_back(value)

StatHistory.getValueAt.source:
func getValueAt(eventNum):

	if eventNum < 0:
		return values[0]

	if eventNumbers[ - 1] <= eventNum:
		return values[ - 1]

	var index = eventNumbers.bsearch(eventNum, false) - 1
	return values[index]

StatHistory.getLastEntryBefore.source:
func getLastEntryBefore(eventNum):



	var index = eventNumbers.bsearch(eventNum, false) - 1
	return [eventNumbers[index], values[index]]

StatHistory.addValueAcc.source:
func addValueAcc(eventNum, value):
	var curValue = 0
	if not values.empty():
		curValue = values[ - 1]
	addValue(eventNum, curValue + value)
